package pbl6.ctsv.mghp.configuration;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.JsonParser;import jakarta.servlet.http.*;import java.io.*;import java.net.URI;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import pbl6.ctsv.auth.AuthAccess;
@RestController @RequestMapping("/api/ctsv/mghp") @ConditionalOnProperty(name="ctsv.mghp.configuration.enabled",havingValue="true")
class MghpController {
 final AuthAccess auth;final ConfigurationAccess access;final ConfigurationRepository repo;final PolicyService policies;final RoundService rounds;final ObjectMapper json;
 MghpController(AuthAccess auth,ConfigurationAccess access,ConfigurationRepository repo,PolicyService policies,RoundService rounds,ObjectMapper json){this.auth=auth;this.access=access;this.repo=repo;this.policies=policies;this.rounds=rounds;this.json=json.copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);}
 AuthAccess.Principal principal(HttpServletRequest r){var h=Collections.list(r.getHeaders("Authorization"));if(h.size()!=1||!h.getFirst().startsWith("Bearer "))throw new ConfigFailure(401,"UNAUTHENTICATED");return auth.verifyAccessToken(h.getFirst().substring(7));}
 long id(String field,String value){try{return ConfigRules.id(value);}catch(ConfigFailure e){throw ConfigFailure.invalid(field);}}
 @GetMapping("/chinh-sach")Object policies(HttpServletRequest r)throws Exception{var p=principal(r);query(r);return access.manager(p,false,u->policies.list());}
 @GetMapping("/chinh-sach/{idChinhSach}/phien-ban")Object versions(@PathVariable String idChinhSach,HttpServletRequest r)throws Exception{var p=principal(r);query(r);return access.manager(p,false,u->repo.versions(id("idChinhSach",idChinhSach)));}
 @GetMapping("/phien-ban-chinh-sach/{idPhienBan}")ResponseEntity<?> policy(@PathVariable String idPhienBan,HttpServletRequest r)throws Exception{var p=principal(r);query(r);return response(access.manager(p,false,u->policies.detail(id("idPhienBan",idPhienBan))),200,true,null);}
 @PostMapping("/chinh-sach/{idChinhSach}/phien-ban")ResponseEntity<?> createPolicy(@PathVariable String idChinhSach,HttpServletRequest r)throws Exception{var p=principal(r);var n=body(r,PolicyRules.FIELDS);var v=access.manager(p,true,u->policies.create(id("idChinhSach",idChinhSach),n,u));return response(v,201,true,"/api/ctsv/mghp/phien-ban-chinh-sach/"+((Map<?,?>)v.body()).get("id"));}
 @PutMapping("/phien-ban-chinh-sach/{idPhienBan}")ResponseEntity<?> updatePolicy(@PathVariable String idPhienBan,HttpServletRequest r)throws Exception{var p=principal(r);var n=body(r,PolicyRules.FIELDS);return response(access.manager(p,true,u->policies.update(id("idPhienBan",idPhienBan),n,tag(r),u)),200,false,null);}
 @PostMapping("/phien-ban-chinh-sach/{idPhienBan}/xac-nhan")ResponseEntity<?> confirm(@PathVariable String idPhienBan,HttpServletRequest r)throws Exception{var p=principal(r);var n=body(r,"evidence");return response(access.manager(p,true,u->policies.confirm(id("idPhienBan",idPhienBan),n,tag(r),u)),200,true,null);}
 @GetMapping("/dot-xet")Object rounds(HttpServletRequest r)throws Exception{var p=principal(r);query(r,"semesterId","page","size");var page=ConfigRules.page(r.getParameter("page"),r.getParameter("size"));Long s=r.getParameter("semesterId")==null?null:id("semesterId",r.getParameter("semesterId"));return access.reader(p,(manager,u)->rounds.list(manager,s,page));}
 @GetMapping("/dot-xet/{idDotXet}")ResponseEntity<?> round(@PathVariable String idDotXet,HttpServletRequest r)throws Exception{var p=principal(r);query(r);return access.reader(p,(manager,u)->response(rounds.detail(id("idDotXet",idDotXet),manager),200,manager,null));}
 @PostMapping("/dot-xet")ResponseEntity<?> createRound(HttpServletRequest r)throws Exception{var p=principal(r);var n=body(r,RoundRules.FIELDS);var v=access.manager(p,true,u->rounds.create(n,u));return response(v,201,true,"/api/ctsv/mghp/dot-xet/"+((Map<?,?>)v.body()).get("id"));}
 @PutMapping("/dot-xet/{idDotXet}")ResponseEntity<?> updateRound(@PathVariable String idDotXet,HttpServletRequest r)throws Exception{var p=principal(r);var n=body(r,RoundRules.FIELDS);return response(access.manager(p,true,u->rounds.update(id("idDotXet",idDotXet),n,tag(r),u)),200,false,null);}
 @PostMapping("/dot-xet/{idDotXet}/mo")ResponseEntity<?> open(@PathVariable String idDotXet,HttpServletRequest r)throws Exception{var p=principal(r);query(r);return response(access.manager(p,true,u->rounds.transition(id("idDotXet",idDotXet),"open",tag(r),null,u)),200,true,null);}
 @PostMapping("/dot-xet/{idDotXet}/dong-nhan-ho-so")ResponseEntity<?> close(@PathVariable String idDotXet,HttpServletRequest r)throws Exception{return transition(idDotXet,r,"close");}
 @PostMapping("/dot-xet/{idDotXet}/hoan-tat")ResponseEntity<?> complete(@PathVariable String idDotXet,HttpServletRequest r)throws Exception{return transition(idDotXet,r,"complete");}
 ResponseEntity<?> transition(String id,HttpServletRequest r,String action)throws Exception{var p=principal(r);var n=body(r,"reason");String reason=ConfigRules.text(n,"reason",4000,true);return response(access.manager(p,true,u->rounds.transition(id("idDotXet",id),action,tag(r),reason,u)),200,true,null);}
 String tag(HttpServletRequest r){if(Collections.list(r.getHeaders("If-Match")).size()>1)throw ConfigFailure.invalid("If-Match");return r.getHeader("If-Match");}
 ResponseEntity<?> response(PolicyService.View v,int status,boolean tag,String location){var b=ResponseEntity.status(status).cacheControl(CacheControl.noStore());if(tag&&v.tag()!=null)b.eTag(v.tag());if(location!=null)b.location(URI.create(location));return b.body(v.body());}
 void query(HttpServletRequest r,String...keys)throws IOException{if(r.getInputStream().read()!=-1)throw ConfigFailure.invalid("body");for(var k:r.getParameterMap().keySet())if(!Set.of(keys).contains(k)||r.getParameterValues(k).length!=1)throw ConfigFailure.invalid(k);}
 JsonNode body(HttpServletRequest r,String fields)throws IOException{if(r.getQueryString()!=null)throw ConfigFailure.invalid("query");try{if(r.getContentType()==null||!MediaType.APPLICATION_JSON.includes(MediaType.parseMediaType(r.getContentType())))throw new ConfigFailure(415,"UNSUPPORTED_MEDIA_TYPE");}catch(InvalidMediaTypeException e){throw new ConfigFailure(415,"UNSUPPORTED_MEDIA_TYPE");}if(r.getHeader("Content-Encoding")!=null&&!"identity".equals(r.getHeader("Content-Encoding")))throw new ConfigFailure(415,"UNSUPPORTED_MEDIA_TYPE");byte[] bytes=r.getInputStream().readNBytes(1048577);if(bytes.length>1048576)throw new ConfigFailure(413,"PAYLOAD_TOO_LARGE");JsonNode n;try{n=json.readTree(StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes)).toString());}catch(Exception e){throw ConfigFailure.invalid("body");}ConfigRules.shape(n,fields);return n;}
}
